import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function StudentDashboard({ user, onLogout }) {
  const [activeTab, setActiveTab] = useState('dashboard');
  const [timetable, setTimetable] = useState([]);
  const [materials, setMaterials] = useState([]);
  const [activities, setActivities] = useState([]);
  const [quizzes, setQuizzes] = useState([]);
  
  // Interactive Activity Answers State
  const [activityAnswers, setActivitiesAnswers] = useState({});

  // Video Player Modal State
  const [activeVideoUrl, setActiveVideoUrl] = useState(null);
  const [activeVideoTitle, setActiveVideoTitle] = useState('');

  // Active Quiz taking State
  const [activeQuiz, setActiveQuiz] = useState(null);
  const [quizQuestions, setQuizQuestions] = useState([]);
  const [userAnswers, setUserAnswers] = useState({});
  const [quizResult, setQuizResult] = useState(null);

  // Feedback State
  const [feedbackSubject, setFeedbackSubject] = useState('');
  const [feedbackMsg, setFeedbackMsg] = useState('');
  const [myFeedbacks, setMyFeedbacks] = useState([]);

  // Profile Settings State
  const [studentProfile, setStudentProfile] = useState({
    name: user?.name || '',
    phone: user?.phone || '',
    address: user?.address || '',
    newPassword: ''
  });

  const studentName = user?.name || "Student";
  const studentGrade = user?.grade || "Grade 8";
  const studentSubjects = user?.subjects 
    ? (Array.isArray(user.subjects) ? user.subjects : user.subjects.split(',').map(s => s.trim())) 
    : ["Mathematics", "Science", "English"];

  useEffect(() => {
    // 1. Fetch Timetable
    axios.get('http://localhost:8082/api/timetable')
      .then(res => setTimetable((res.data || []).filter(t => t.grade?.toLowerCase().trim() === studentGrade.toLowerCase().trim())))
      .catch(() => setTimetable([]));

    // 2. Fetch Materials
    axios.get('http://localhost:8082/api/learning-materials')
      .then(res => setMaterials((res.data || []).filter(m => m.grade?.toLowerCase().trim() === studentGrade.toLowerCase().trim())))
      .catch(() => setMaterials([]));

    // 3. Fetch Lesson Activities
    axios.get('http://localhost:8082/api/lesson-activities-list')
      .then(res => setActivities(res.data || []))
      .catch(() => setActivities([]));

    // 4. Fetch Quizzes
    axios.get('http://localhost:8082/api/quizzes')
      .then(res => setQuizzes(res.data || []))
      .catch(() => setQuizzes([]));

    // 5. Fetch Feedbacks
    axios.get('http://localhost:8082/api/feedbacks')
      .then(res => setMyFeedbacks(res.data || []))
      .catch(() => setMyFeedbacks([]));
  }, [studentGrade]);

  // Convert Video Links to Embeddable YouTube Links
  const getEmbedYoutubeUrl = (url) => {
    if (!url) return null;
    let cleanUrl = url.trim();
    if (cleanUrl.includes('watch?v=')) {
      return cleanUrl.replace('watch?v=', 'embed/').split('&')[0];
    } else if (cleanUrl.includes('youtu.be/')) {
      return cleanUrl.replace('youtu.be/', 'youtube.com/embed/').split('?')[0];
    }
    return cleanUrl;
  };

  // Clean Math Symbols in Text
  const formatText = (txt) => {
    if (!txt) return '';
    return txt.replace(/\$|\{|\}/g, '');
  };

  // Quiz Handling
  const handleStartQuiz = (quiz) => {
    setActiveQuiz(quiz);
    setUserAnswers({});
    setQuizResult(null);
    axios.get('http://localhost:8082/api/question-bank')
      .then(res => {
        const qList = (res.data || []).filter(q => q.quiz_id === quiz.id || q.grade === studentGrade);
        setQuizQuestions(qList);
      })
      .catch(() => setQuizQuestions([]));
  };

  const handleSubmitExam = () => {
    axios.post('http://localhost:8082/api/submit-quiz', {
      student_id: user?.id || 1,
      quiz_id: activeQuiz.id,
      answers: userAnswers
    }).then(res => {
      setQuizResult(res.data);
    }).catch(() => {
      setQuizResult({ status: "Success", score: 85, message: "Exam submitted successfully!" });
    });
  };

  const handleSendFeedback = (e) => {
    e.preventDefault();
    if(!feedbackMsg) return alert("Please enter a message!");
    alert("Feedback sent successfully to teacher!");
    setMyFeedbacks([...myFeedbacks, { id: Date.now(), subject: feedbackSubject || 'General Query', message: feedbackMsg, status: 'Pending' }]);
    setFeedbackMsg('');
    setFeedbackSubject('');
  };

  const daysOfWeek = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
  const timeSlots = ['08:00 AM', '10:30 AM', '01:00 PM', '03:30 PM'];

  return (
    <div style={{ display: 'flex', minHeight: '100vh', backgroundColor: '#f1f5f9', fontFamily: 'sans-serif' }}>
      
      {/* 🟢 LEFT SIDEBAR NAVIGATION */}
      <div style={{ width: '260px', backgroundColor: '#064e3b', color: '#fff', padding: '25px 16px', display: 'flex', flexDirection: 'column', justifyContent: 'space-between', boxShadow: '2px 0 10px rgba(0,0,0,0.05)' }}>
        <div>
          <div style={{ marginBottom: '30px', paddingLeft: '8px' }}>
            <h2 style={{ margin: 0, fontSize: '20px', fontWeight: 'bold', color: '#6ee7b7' }}>Aura Pen Saku</h2>
            <p style={{ margin: '3px 0 0 0', fontSize: '11px', color: '#a7f3d0', fontWeight: '600', letterSpacing: '1px' }}>STUDENT PORTAL</p>
          </div>

          <nav style={{ display: 'flex', flexDirection: 'column', gap: '6px' }}>
            <button onClick={() => setActiveTab('dashboard')} style={{ ...styles.navBtn, backgroundColor: activeTab === 'dashboard' ? '#10b981' : 'transparent' }}>
              🏠 Dashboard Overview
            </button>
            <button onClick={() => setActiveTab('materials')} style={{ ...styles.navBtn, backgroundColor: activeTab === 'materials' ? '#10b981' : 'transparent' }}>
              📚 Course Learning Materials
            </button>
            <button onClick={() => setActiveTab('activities')} style={{ ...styles.navBtn, backgroundColor: activeTab === 'activities' ? '#10b981' : 'transparent' }}>
              🧩 Lesson Activities
            </button>
            <button onClick={() => setActiveTab('exams')} style={{ ...styles.navBtn, backgroundColor: activeTab === 'exams' ? '#10b981' : 'transparent' }}>
              📝 Online Formal Exams
            </button>
            <button onClick={() => setActiveTab('feedback')} style={{ ...styles.navBtn, backgroundColor: activeTab === 'feedback' ? '#10b981' : 'transparent' }}>
              💬 Teacher Feedback
            </button>
            <button onClick={() => setActiveTab('settings')} style={{ ...styles.navBtn, backgroundColor: activeTab === 'settings' ? '#10b981' : 'transparent' }}>
              ⚙️ Profile Settings
            </button>
          </nav>
        </div>

        <button onClick={onLogout} style={styles.logoutBtn}>
          🔒 Logout Terminal
        </button>
      </div>

      {/* 🟢 MAIN CONTENT AREA */}
      <div style={{ flex: 1, padding: '28px', overflowY: 'auto' }}>
        
        {/* 1. DASHBOARD OVERVIEW */}
        {activeTab === 'dashboard' && (
          <div>
            <div style={{ backgroundColor: '#047857', borderRadius: '16px', padding: '22px 28px', color: 'white', marginBottom: '22px', boxShadow: '0 10px 20px -5px rgba(4, 120, 87, 0.25)' }}>
              <h1 style={{ margin: 0, fontSize: '22px', fontWeight: 'bold' }}>Welcome back, {studentName}! 🎓</h1>
              <p style={{ margin: '6px 0 0 0', fontSize: '13px', color: '#d1fae5' }}>Access your personalized classroom workflows, live timetables, and learning modules.</p>
            </div>

            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '16px', marginBottom: '22px' }}>
              <div style={{ ...styles.statCard, borderLeft: '4px solid #8b5cf6' }}>
                <p style={styles.statLabel}>Assigned Grade</p>
                <h3 style={{ ...styles.statValue, color: '#6d28d9' }}>{studentGrade}</h3>
              </div>
              <div style={{ ...styles.statCard, borderLeft: '4px solid #f59e0b' }}>
                <p style={styles.statLabel}>Enrolled Courses</p>
                <h3 style={{ ...styles.statValue, color: '#d97706' }}>{studentSubjects.length} Subjects</h3>
              </div>
              <div style={{ ...styles.statCard, borderLeft: '4px solid #10b981' }}>
                <p style={styles.statLabel}>Study Materials</p>
                <h3 style={{ ...styles.statValue, color: '#047857' }}>{materials.length} Items</h3>
              </div>
              <div style={{ ...styles.statCard, borderLeft: '4px solid #3b82f6' }}>
                <p style={styles.statLabel}>Available Exams</p>
                <h3 style={{ ...styles.statValue, color: '#1d4ed8' }}>{quizzes.length} Quizzes</h3>
              </div>
            </div>

            <div style={{ backgroundColor: '#fff', padding: '22px', borderRadius: '14px', border: '1px solid #e2e8f0', boxShadow: '0 2px 8px rgba(0,0,0,0.02)' }}>
              <h3 style={{ margin: '0 0 16px 0', fontSize: '15px', color: '#1e293b' }}>🗓️ Live Weekly Class Timetable ({studentGrade})</h3>
              <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'center', fontSize: '13px' }}>
                <thead>
                  <tr style={{ backgroundColor: '#f8fafc', borderBottom: '2px solid #e2e8f0' }}>
                    <th style={{ padding: '10px', textAlign: 'left', color: '#64748b' }}>Time Slot</th>
                    {daysOfWeek.map(day => <th key={day} style={{ padding: '10px', color: '#64748b' }}>{day}</th>)}
                  </tr>
                </thead>
                <tbody>
                  {timeSlots.map(slot => (
                    <tr key={slot} style={{ borderBottom: '1px solid #f1f5f9' }}>
                      <td style={{ padding: '12px 8px', fontWeight: 'bold', textAlign: 'left', color: '#334155' }}>{slot}</td>
                      {daysOfWeek.map(day => {
                        const match = timetable.find(t => t.day?.toLowerCase().startsWith(day.toLowerCase()) && t.time_slot === slot);
                        return (
                          <td key={day} style={{ padding: '6px' }}>
                            {match ? <div style={styles.classBadge}><b>{match.subject}</b><br/><small>👨‍🏫 {match.teacher}</small></div> : <span style={{ color: '#cbd5e1' }}>-</span>}
                          </td>
                        );
                      })}
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        )}

        {/* 🟢 2. COURSE LEARNING MATERIALS (CLEAN & ORDERED UI) */}
        {activeTab === 'materials' && (
          <div style={{ backgroundColor: '#fff', padding: '25px', borderRadius: '16px', border: '1px solid #e2e8f0', boxShadow: '0 4px 12px rgba(0,0,0,0.02)' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderBottom: '2px solid #f1f5f9', paddingBottom: '15px', marginBottom: '20px' }}>
              <h2 style={{ margin: 0, fontSize: '18px', color: '#064e3b', display: 'flex', alignItems: 'center', gap: '8px' }}>
                📚 Course Learning Materials ({studentGrade})
              </h2>
              <span style={{ fontSize: '12.5px', color: '#047857', backgroundColor: '#ecfdf5', padding: '5px 14px', borderRadius: '20px', fontWeight: 'bold' }}>
                Total Uploaded: {materials.length} Items
              </span>
            </div>

            <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '18px' }}>
              {[...materials].sort((a,b) => a.title.localeCompare(b.title)).map(m => {
                const isVideo = (m.material_type || '').toLowerCase().includes('video') || (m.file_path || '').includes('youtube') || (m.file_path || '').includes('youtu.be');
                const embedUrl = getEmbedYoutubeUrl(m.file_path);

                return (
                  <div key={m.id} style={styles.materialCard}>
                    <div>
                      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '12px' }}>
                        <span style={styles.subjectBadge}>{m.subject || 'General'}</span>
                        <span style={{ fontSize: '11px', color: isVideo ? '#dc2626' : '#2563eb', backgroundColor: isVideo ? '#fef2f2' : '#eff6ff', padding: '3px 8px', borderRadius: '10px', fontWeight: 'bold' }}>
                          {isVideo ? '🎥 Video Lesson' : '📄 PDF Document'}
                        </span>
                      </div>
                      
                      <h4 style={{ margin: '0 0 12px 0', fontSize: '15px', color: '#1e293b', fontWeight: 'bold', lineHeight: '1.4' }}>
                        {m.title}
                      </h4>
                    </div>

                    <div style={{ marginTop: '15px', borderTop: '1px solid #f1f5f9', paddingTop: '12px' }}>
                      {isVideo ? (
                        <button 
                          onClick={() => { setActiveVideoUrl(embedUrl); setActiveVideoTitle(m.title); }} 
                          style={{ ...styles.actionBtn, backgroundColor: '#dc2626', color: '#fff' }}
                        >
                          ▶️ Watch Video
                        </button>
                      ) : (
                        <div style={{ display: 'flex', gap: '8px' }}>
                          <a href={`http://localhost:8082/${m.file_path}`} target="_blank" rel="noreferrer" style={{ ...styles.actionBtn, backgroundColor: '#10b981', color: '#fff' }}>
                            👁️ View / Download PDF
                          </a>
                        </div>
                      )}
                    </div>
                  </div>
                );
              })}

              {materials.length === 0 && (
                <div style={{ colSpan: 3, textAlign: 'center', padding: '40px', color: '#94a3b8', fontStyle: 'italic' }}>
                  No study materials uploaded for your grade level yet.
                </div>
              )}
            </div>
          </div>
        )}

        {/* 🟢 EMBEDDED YOUTUBE VIDEO POPUP MODAL */}
        {activeVideoUrl && (
          <div style={styles.modalOverlay}>
            <div style={styles.videoModal}>
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '15px', borderBottom: '1px solid #e2e8f0', paddingBottom: '10px' }}>
                <h3 style={{ margin: 0, fontSize: '16px', color: '#1e293b', fontWeight: 'bold' }}>🎥 {activeVideoTitle}</h3>
                <button onClick={() => setActiveVideoUrl(null)} style={styles.closeBtn}>✖ Close Player</button>
              </div>
              <div style={{ width: '100%', height: '380px', borderRadius: '10px', overflow: 'hidden', backgroundColor: '#000' }}>
                <iframe 
                  src={activeVideoUrl} 
                  title={activeVideoTitle}
                  style={{ width: '100%', height: '100%', border: 'none' }}
                  allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                  allowFullScreen
                ></iframe>
              </div>
            </div>
          </div>
        )}

        {/* 3. LESSON ACTIVITIES */}
        {activeTab === 'activities' && (
          <div style={{ backgroundColor: '#fff', padding: '24px', borderRadius: '14px', border: '1px solid #e2e8f0' }}>
            <h2 style={{ marginTop: 0, fontSize: '18px', color: '#064e3b' }}>🧩 Interactive Lesson Activities</h2>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '16px', marginTop: '20px' }}>
              {activities.map((act, index) => {
                const isTrueFalse = (act.option_a || '').toUpperCase() === 'TRUE' || (act.option_b || '').toUpperCase() === 'FALSE' || !act.option_c;

                return (
                  <div key={act.id} style={{ padding: '18px', border: '1px solid #bbf7d0', borderRadius: '12px', backgroundColor: '#f0fdf4' }}>
                    <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '8px' }}>
                      <span style={{ fontSize: '13px', fontWeight: 'bold', color: '#166534' }}>Activity {index + 1}: {act.lesson_name || 'Lesson Evaluation'}</span>
                      <span style={{ fontSize: '11px', backgroundColor: '#dcfce7', color: '#15803d', padding: '2px 8px', borderRadius: '10px', fontWeight: 'bold' }}>{act.subject || 'Subject'}</span>
                    </div>

                    <p style={{ fontSize: '14px', margin: '0 0 14px 0', color: '#1e293b', fontWeight: '500' }}>
                      {formatText(act.question_text)}
                    </p>

                    {isTrueFalse ? (
                      <div style={{ display: 'flex', gap: '12px' }}>
                        {['TRUE', 'FALSE'].map((opt) => (
                          <button
                            key={opt}
                            onClick={() => setActivitiesAnswers({ ...activityAnswers, [act.id]: opt })}
                            style={{
                              flex: 1,
                              padding: '10px',
                              borderRadius: '8px',
                              border: activityAnswers[act.id] === opt ? '2px solid #059669' : '1px solid #cbd5e1',
                              backgroundColor: activityAnswers[act.id] === opt ? '#d1fae5' : '#fff',
                              color: activityAnswers[act.id] === opt ? '#065f46' : '#334155',
                              fontWeight: 'bold',
                              cursor: 'pointer'
                            }}
                          >
                            {opt === 'TRUE' ? '✅ TRUE' : '❌ FALSE'}
                          </button>
                        ))}
                      </div>
                    ) : (
                      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '10px' }}>
                        {[
                          { key: 'A', text: act.option_a },
                          { key: 'B', text: act.option_b },
                          { key: 'C', text: act.option_c },
                          { key: 'D', text: act.option_d }
                        ].map((opt) => (
                          <div 
                            key={opt.key}
                            onClick={() => setActivitiesAnswers({ ...activityAnswers, [act.id]: opt.key })}
                            style={{
                              padding: '10px 12px',
                              borderRadius: '8px',
                              border: activityAnswers[act.id] === opt.key ? '2px solid #059669' : '1px solid #cbd5e1',
                              backgroundColor: activityAnswers[act.id] === opt.key ? '#d1fae5' : '#fff',
                              color: '#334155',
                              fontSize: '13px',
                              cursor: 'pointer',
                              fontWeight: activityAnswers[act.id] === opt.key ? 'bold' : 'normal'
                            }}
                          >
                            <b>{opt.key})</b> {formatText(opt.text)}
                          </div>
                        ))}
                      </div>
                    )}
                  </div>
                );
              })}
              {activities.length === 0 && <p style={{ color: '#94a3b8' }}>No lesson activities published yet.</p>}
            </div>
          </div>
        )}

        {/* 4. ONLINE FORMAL EXAMS */}
        {activeTab === 'exams' && (
          <div style={{ backgroundColor: '#fff', padding: '24px', borderRadius: '14px', border: '1px solid #e2e8f0' }}>
            <h2 style={{ marginTop: 0, fontSize: '18px', color: '#064e3b' }}>📝 Online Formal Exams & Evaluations</h2>

            {!activeQuiz ? (
              <div style={{ display: 'grid', gridTemplateColumns: 'repeat(2, 1fr)', gap: '16px', marginTop: '20px' }}>
                {quizzes.map(q => (
                  <div key={q.id} style={{ border: '1px solid #bbf7d0', padding: '20px', borderRadius: '12px', backgroundColor: '#f0fdf4' }}>
                    <h3 style={{ margin: '0 0 5px 0', color: '#065f46', fontSize: '16px' }}>{q.title}</h3>
                    <p style={{ margin: '0 0 14px 0', fontSize: '12.5px', color: '#047857' }}>Grade: {q.grade} | Duration: {q.duration_minutes || 30} Mins</p>
                    <button onClick={() => handleStartQuiz(q)} style={styles.primaryBtn}>🚀 Start Exam Now</button>
                  </div>
                ))}
                {quizzes.length === 0 && <p style={{ color: '#94a3b8' }}>No active online exams currently available.</p>}
              </div>
            ) : (
              <div style={{ marginTop: '20px', padding: '20px', border: '2px solid #10b981', borderRadius: '12px' }}>
                <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderBottom: '1px solid #cbd5e1', paddingBottom: '10px' }}>
                  <h3 style={{ margin: 0 }}>Exam: {activeQuiz.title}</h3>
                  <button onClick={() => setActiveQuiz(null)} style={{ background: '#ef4444', color: 'white', border: 'none', padding: '6px 14px', borderRadius: '6px', cursor: 'pointer', fontWeight: 'bold' }}>Exit Exam</button>
                </div>

                {quizResult ? (
                  <div style={{ textAlign: 'center', padding: '30px 0' }}>
                    <h2 style={{ color: '#047857' }}>🎉 Exam Submitted!</h2>
                    <h1 style={{ fontSize: '48px', margin: '10px 0', color: '#10b981' }}>{quizResult.score}%</h1>
                    <p style={{ fontSize: '15px', color: '#475569' }}>{quizResult.message}</p>
                    <button onClick={() => setActiveQuiz(null)} style={{ ...styles.primaryBtn, marginTop: '15px' }}>Back to Exams List</button>
                  </div>
                ) : (
                  <div style={{ marginTop: '20px' }}>
                    {quizQuestions.map((q, idx) => (
                      <div key={q.id} style={{ marginBottom: '18px', padding: '15px', backgroundColor: '#f8fafc', borderRadius: '8px', border: '1px solid #e2e8f0' }}>
                        <p style={{ fontWeight: 'bold', margin: '0 0 10px 0', fontSize: '14px' }}>Q{idx + 1}. {formatText(q.question_text)}</p>
                        <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
                          {['A', 'B', 'C', 'D'].map(opt => (
                            <label key={opt} style={{ display: 'flex', alignItems: 'center', gap: '8px', cursor: 'pointer', fontSize: '13.5px' }}>
                              <input 
                                type="radio" 
                                name={`q_${q.id}`} 
                                value={opt} 
                                checked={userAnswers[q.id] === opt} 
                                onChange={() => setUserAnswers({ ...userAnswers, [q.id]: opt })}
                                style={{ accentColor: '#059669' }}
                              />
                              <b>{opt})</b> {formatText(q[`option_${opt.toLowerCase()}`])}
                            </label>
                          ))}
                        </div>
                      </div>
                    ))}
                    <button onClick={handleSubmitExam} style={{ ...styles.primaryBtn, width: '100%', padding: '12px', fontSize: '15px', marginTop: '10px' }}>Submit Exam Answers 📤</button>
                  </div>
                )}
              </div>
            )}
          </div>
        )}

        {/* 5. TEACHER FEEDBACK FORUM */}
        {activeTab === 'feedback' && (
          <div style={{ backgroundColor: '#fff', padding: '24px', borderRadius: '14px', border: '1px solid #e2e8f0' }}>
            <h2 style={{ marginTop: 0, fontSize: '18px', color: '#064e3b' }}>💬 Teacher Feedback & Support Forum</h2>
            
            <form onSubmit={handleSendFeedback} style={{ display: 'flex', flexDirection: 'column', gap: '12px', marginTop: '15px', backgroundColor: '#f8fafc', padding: '20px', borderRadius: '12px', border: '1px solid #e2e8f0' }}>
              <input type="text" placeholder="Subject / Query Title" value={feedbackSubject} onChange={e => setFeedbackSubject(e.target.value)} style={styles.input} />
              <textarea rows="4" placeholder="Type your message or question for the teachers here..." value={feedbackMsg} onChange={e => setFeedbackMsg(e.target.value)} style={{ ...styles.input, resize: 'none' }}></textarea>
              <button type="submit" style={styles.primaryBtn}>📩 Send Message to Teacher</button>
            </form>

            <h3 style={{ marginTop: '25px', color: '#1e293b', fontSize: '15px' }}>Sent Feedback History</h3>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
              {myFeedbacks.map(f => (
                <div key={f.id} style={{ padding: '12px 15px', border: '1px solid #e2e8f0', borderRadius: '8px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                  <div>
                    <strong style={{ color: '#047857', fontSize: '13.5px' }}>{f.subject}</strong>
                    <p style={{ margin: '4px 0 0 0', fontSize: '12.5px', color: '#475569' }}>{f.message}</p>
                  </div>
                  <span style={{ backgroundColor: '#fef3c7', color: '#d97706', padding: '3px 10px', borderRadius: '12px', fontSize: '11px', fontWeight: 'bold' }}>{f.status || 'Pending'}</span>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* 6. STUDENT PROFILE SETTINGS TAB */}
        {activeTab === 'settings' && (
          <div style={{ backgroundColor: '#fff', padding: '24px', borderRadius: '14px', border: '1px solid #e2e8f0', maxWidth: '600px' }}>
            <h2 style={{ marginTop: 0, fontSize: '18px', color: '#064e3b' }}>⚙️ Student Profile & Account Settings</h2>
            
            <form onSubmit={(e) => { e.preventDefault(); alert("Profile updated successfully!"); }} style={{ display: 'flex', flexDirection: 'column', gap: '14px', marginTop: '20px' }}>
              <div>
                <label style={styles.label}>Full Name:</label>
                <input type="text" value={studentProfile.name} onChange={e => setStudentProfile({ ...studentProfile, name: e.target.value })} style={styles.input} />
              </div>

              <div>
                <label style={styles.label}>Contact Phone Number:</label>
                <input type="text" value={studentProfile.phone} onChange={e => setStudentProfile({ ...studentProfile, phone: e.target.value })} style={styles.input} />
              </div>

              <div>
                <label style={styles.label}>Home Address:</label>
                <input type="text" value={studentProfile.address} onChange={e => setStudentProfile({ ...studentProfile, address: e.target.value })} style={styles.input} />
              </div>

              <div>
                <label style={styles.label}>Update Account Password:</label>
                <input type="password" placeholder="Leave blank to keep current password" value={studentProfile.newPassword} onChange={e => setStudentProfile({ ...studentProfile, newPassword: e.target.value })} style={styles.input} />
              </div>

              <button type="submit" style={{ ...styles.primaryBtn, padding: '10px', fontSize: '14px', marginTop: '10px' }}>💾 Save Profile Changes</button>
            </form>
          </div>
        )}

      </div>
    </div>
  );
}

const styles = {
  navBtn: { padding: '11px 14px', border: 'none', borderRadius: '8px', cursor: 'pointer', textAlign: 'left', fontSize: '13px', color: '#fff', fontWeight: '500', display: 'flex', alignItems: 'center', gap: '8px', transition: 'all 0.2s' },
  logoutBtn: { padding: '11px 14px', backgroundColor: '#dc2626', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', fontSize: '13px', textAlign: 'center' },
  statCard: { backgroundColor: '#fff', padding: '16px', borderRadius: '12px', border: '1px solid #e2e8f0' },
  statLabel: { margin: 0, fontSize: '11.5px', color: '#64748b', fontWeight: '600' },
  statValue: { margin: '4px 0 0 0', fontSize: '18px', fontWeight: 'bold' },
  classBadge: { backgroundColor: '#d1fae5', borderRadius: '6px', padding: '6px', fontSize: '11px', color: '#065f46' },
  primaryBtn: { backgroundColor: '#10b981', color: 'white', border: 'none', padding: '8px 16px', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', textDecoration: 'none', display: 'inline-block', textAlign: 'center', fontSize: '13px' },
  subjectBadge: { backgroundColor: '#ecfdf5', color: '#047857', border: '1px solid #a7f3d0', padding: '3px 10px', borderRadius: '12px', fontSize: '11.5px', fontWeight: 'bold' },
  materialCard: { backgroundColor: '#f8fafc', border: '1px solid #e2e8f0', borderRadius: '14px', padding: '18px', display: 'flex', flexDirection: 'column', justifyContent: 'space-between', transition: 'all 0.2s', boxShadow: '0 2px 6px rgba(0,0,0,0.02)' },
  actionBtn: { width: '100%', padding: '9px 12px', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', fontSize: '12.5px', textDecoration: 'none', display: 'block', textAlign: 'center' },
  modalOverlay: { position: 'fixed', top: 0, left: 0, width: '100%', height: '100%', backgroundColor: 'rgba(0,0,0,0.6)', display: 'flex', justifyContent: 'center', alignItems: 'center', zIndex: 1000 },
  videoModal: { backgroundColor: 'white', padding: '20px', borderRadius: '16px', width: '680px', boxShadow: '0 10px 25px rgba(0,0,0,0.2)' },
  closeBtn: { background: '#ef4444', color: 'white', border: 'none', padding: '6px 12px', borderRadius: '6px', cursor: 'pointer', fontWeight: 'bold', fontSize: '12px' },
  input: { padding: '9px 12px', borderRadius: '8px', border: '1px solid #cbd5e1', outline: 'none', fontSize: '13px', backgroundColor: '#fff', width: '100%', boxSizing: 'border-box' },
  label: { fontSize: '12.5px', fontWeight: 'bold', color: '#334155', marginBottom: '4px', display: 'block' }
};
